#pragma once
#include <cstdint>

struct VnCharRange
{
    uint16_t lo;
    uint16_t hi;
};

constexpr bool vn_in_ranges(char16_t ch, const VnCharRange* ranges, int32_t count) noexcept
{
    uint16_t code = static_cast<uint16_t>(ch);
    int32_t left = 0;
    int32_t right = count - 1;
    while (left <= right)
    {
        int32_t mid = left + ((right - left) >> 1);
        if (code < ranges[mid].lo)
            right = mid - 1;
        else if (code > ranges[mid].hi)
            left = mid + 1;
        else
            return true;
    }
    return false;
}

