constexpr bool vn_is_non_spacing_mark(char16_t ch) noexcept
{
    return vn_in_ranges(ch, VN_UNICODE_MN_RANGES, 213);
}

constexpr bool vn_is_combining_mark(char16_t ch) noexcept
{
    return vn_in_ranges(ch, VN_UNICODE_MN_RANGES, 213) ||
           vn_in_ranges(ch, VN_UNICODE_MCME_RANGES, 117);
}

constexpr bool vn_is_letter_or_digit(char16_t ch) noexcept
{
    return vn_in_ranges(ch, VN_UNICODE_LOD_RANGES, 398);
}
